function specialPerm(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  const full = (1 << n) - 1;
  const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    dp[1 << i][i] = 1;
  }
  for (let mask = 1; mask < full; mask++) {
    for (let last = 0; last < n; last++) {
      const ways = dp[mask][last];
      if (ways === 0) continue;
      for (let next = 0; next < n; next++) {
        if (mask & (1 << next)) continue;
        if (nums[last] % nums[next] !== 0 && nums[next] % nums[last] !== 0) continue;
        const nextMask = mask | (1 << next);
        dp[nextMask][next] = (dp[nextMask][next] + ways) % MOD;
      }
    }
  }
  let total = 0;
  for (let last = 0; last < n; last++) {
    total = (total + dp[full][last]) % MOD;
  }
  return total;
}

