function specialPerm(nums) {
  // Backtracking over orderings, with exact (unreduced) counts cached per (used set, previous index).
  const n = nums.length;
  const memo = new Map();
  const fits = (a, b) => nums[a] % nums[b] === 0 || nums[b] % nums[a] === 0;
  const extend = (used, prev) => {
    if (used.length === n) return 1;
    const key = used.slice().sort((a, b) => a - b).join(',') + '|' + prev;
    if (memo.has(key)) return memo.get(key);
    let count = 0;
    for (let j = 0; j < n; j++) {
      if (used.includes(j)) continue;
      if (prev !== -1 && !fits(prev, j)) continue;
      used.push(j);
      count += extend(used, j);
      used.pop();
    }
    memo.set(key, count);
    return count;
  };
  // At most 14! (about 8.7e10) orderings, so the exact count stays a safe integer.
  return extend([], -1) % 1000000007;
}

