function generate(rand, size) {
  const n = size === 'large' ? 12 + Math.floor(rand() * 3) : 2 + Math.floor(rand() * 6);
  const style = rand();
  const seen = new Set();
  const nums = [];
  while (nums.length < n) {
    let value;
    if (style < 0.6) {
      // Products of small primes divide each other often, giving many special orderings.
      value = 1;
      for (const p of [2, 3, 5]) {
        const e = Math.floor(rand() * (p === 2 ? 6 : 3));
        for (let t = 0; t < e; t++) value *= p;
      }
      if (rand() < 0.1) value *= 99991;
    } else if (style < 0.85) {
      value = 1 + Math.floor(rand() * 30);
    } else {
      value = 1 + Math.floor(rand() * 1000000000);
    }
    if (!seen.has(value)) {
      seen.add(value);
      nums.push(value);
    }
  }
  return [nums];
}
